import numpy as np
F=np.load('feats.npz'); y=F['y']; FOLDS=np.load('folds_rep.npy')
cfg=np.load('stash_cfg.npz'); S=cfg['S']; A0=cfg['A0']; b0=cfg['b0']
D={}
for l in [7,8,9]:
    D[f'C{l}']=np.concatenate([np.load(f'pass_12/cls_hidden_L{l}.npy'),np.load(f'pass_13/cls_hidden_L{l}.npy')])
    D[f'M{l}']=np.concatenate([np.load(f'pass_13/mean_hidden_L{l}.npy')[:0],np.load(f'pass_12/mean_hidden_L{l}.npy'),np.load(f'pass_13/mean_hidden_L{l}.npy')])
np.savez('featsS.npz',**D)
C9n=D['C9'].astype(np.float64); M9n=D['M9'].astype(np.float64)
C9=F['C9'].astype(np.float64); M9=F['M9'].astype(np.float64); M0=F['M0'].astype(np.float64)
h0=F['C0'][0,S].astype(np.float64)
st=M0@A0.T+b0; z=4*st+h0
al=np.zeros(len(y)); be=np.zeros(len(y)); r2=np.zeros(len(y))
for i in range(len(y)):
    X=np.c_[z[i],np.ones(8)]; c=np.linalg.lstsq(X,C9n[i,S],rcond=None)[0]; al[i],be[i]=c
    r2[i]=1-((C9n[i,S]-X@c)**2).sum()/((C9n[i,S]-C9n[i,S].mean())**2).sum()
print('alpha',al.mean(),al.std()/al.mean(),'r2 min',r2.min())
np.savez('stash_alpha.npz',al=al,be=be)
keep=np.setdiff1d(np.arange(768),S)
def sz(X,tr): m=X[tr].mean(0); s=X[tr].std(0)+1e-9; return (X-m)/s
def ridge(Xtr,Y,lam,Xte):
    xm=Xtr.mean(0); Xc=Xtr-xm; ym=Y.mean(0); n,d=Xc.shape
    if d<=n: Wt=np.linalg.solve(Xc.T@Xc+lam*np.eye(d),Xc.T@(Y-ym))
    else: Wt=Xc.T@np.linalg.solve(Xc@Xc.T+lam*np.eye(n),Y-ym)
    return (Xte-xm)@Wt+ym, Wt
def stash_fold(tr,lam=1000):
    Z=np.concatenate([sz(C9,tr),sz(M9,tr),sz(M0,tr)],1)
    _,Wt=ridge(Z[tr],np.eye(8)[y[tr]]-1/8,lam,Z[:1])
    s=Z[:,1536:]@Wt[1536:]; return s-s[tr].mean(0)
def cv(mode,lams,w=1.0):
    res={l:0 for l in lams}
    for fo in FOLDS:
        for f in range(5):
            tr=fo!=f; te=fo==f
            if mode=='base': X=np.c_[sz(C9,tr),sz(M9,tr)]
            elif mode=='newkeep': X=np.c_[sz(C9n[:,keep],tr),sz(M9n[:,keep],tr)]
            elif mode=='newstash':
                sf=stash_fold(tr); sim=al[:,None]*(4*sf+h0)+be[:,None]
                X=np.c_[sz(C9n[:,keep],tr),sz(M9n[:,keep],tr),w*sz(sim,tr)]
            elif mode=='basestash':
                sf=stash_fold(tr); X=np.c_[sz(C9,tr),sz(M9,tr),w*sz(sf,tr)]
            Y=np.eye(8)[y[tr]]-1/8
            for l in lams: res[l]+=(ridge(X[tr],Y,l,X[te])[0].argmax(1)==y[te]).sum()
    return {l:round(res[l]/len(y)/len(FOLDS),4) for l in lams}
L=[300,1000]
print('base     ',cv('base',L)); print('newkeep  ',cv('newkeep',L))
for w in [1,2]: print('newstash w',w,cv('newstash',L,w)); 
print('basestash',cv('basestash',L))
